:root {
  /* ==========================================================================
     STORM AUTOMOTIVE - DESIGN TOKENS
     Paleta: Preto Profundo / Grafite, Off-White e Laranja Storm
     Tipografia: Sora (Títulos) e Manrope (Textos)
     ========================================================================== */

  /* Cores Principais Obrigatórias */
  --color-bg: #0A0C0E;             /* Fundo preto profundo */
  --color-text-primary: #F7F6F3;   /* Off-white */
  --color-accent: #FF5A1F;         /* Laranja Storm principal */

  /* Cores de Superfície & Grafites Editoriais */
  --color-surface-base: #0E1114;
  --color-surface-elevated: #14181D;
  --color-surface-card: #171C22;
  --color-surface-hover: #1C2229;

  /* Bordas e Delimitadores Sutis */
  --color-border-subtle: rgba(247, 246, 243, 0.08);
  --color-border-default: #1F252D;
  --color-border-strong: #2D343F;

  /* Hierarquia Tipográfica de Cores */
  --color-text-secondary: #9EA6B0;
  --color-text-muted: #656E7B;
  --color-text-inverse: #0A0C0E;

  /* Estados e Variações de Destaque */
  --color-accent-hover: #E64C12;
  --color-accent-active: #CC3F0A;
  --color-accent-subtle: rgba(255, 90, 31, 0.12);
  --color-accent-border: rgba(255, 90, 31, 0.35);

  /* Tipografia */
  --font-heading: "Sora", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-body: "Manrope", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Escala Modular Tipográfica Fluida */
  --text-xs: clamp(0.75rem, 0.72rem + 0.15vw, 0.8125rem);    /* 12px - 13px */
  --text-sm: clamp(0.875rem, 0.84rem + 0.18vw, 0.9375rem);   /* 14px - 15px */
  --text-base: clamp(1rem, 0.96rem + 0.2vw, 1.0625rem);      /* 16px - 17px */
  --text-md: clamp(1.125rem, 1.05rem + 0.38vw, 1.25rem);     /* 18px - 20px */
  --text-lg: clamp(1.25rem, 1.15rem + 0.5vw, 1.5rem);        /* 20px - 24px */
  --text-xl: clamp(1.5rem, 1.35rem + 0.75vw, 1.875rem);      /* 24px - 30px */
  --text-2xl: clamp(1.875rem, 1.65rem + 1.13vw, 2.375rem);   /* 30px - 38px */
  --text-3xl: clamp(2.25rem, 1.95rem + 1.5vw, 3.125rem);     /* 36px - 50px */
  --text-display: clamp(2.75rem, 2.2rem + 2.75vw, 4.5rem);   /* 44px - 72px */

  /* Pesos de Fonte */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --font-weight-extrabold: 800;

  /* Espaçamento entre Letras (Letter-Spacing Editorial) */
  --tracking-tighter: -0.03em;
  --tracking-tight: -0.015em;
  --tracking-normal: 0em;
  --tracking-wide: 0.04em;
  --tracking-wider: 0.08em;
  --tracking-widest: 0.14em;

  /* Altura de Linha (Line-Height) */
  --leading-none: 1;
  --leading-tight: 1.15;
  --leading-snug: 1.3;
  --leading-normal: 1.6;
  --leading-relaxed: 1.75;

  /* Espaçamento Escalar */
  --space-1: 0.25rem;   /* 4px */
  --space-2: 0.5rem;    /* 8px */
  --space-3: 0.75rem;   /* 12px */
  --space-4: 1rem;      /* 16px */
  --space-5: 1.25rem;   /* 20px */
  --space-6: 1.5rem;    /* 24px */
  --space-8: 2rem;      /* 32px */
  --space-10: 2.5rem;   /* 40px */
  --space-12: 3rem;     /* 48px */
  --space-16: 4rem;     /* 64px */
  --space-20: 5rem;     /* 80px */
  --space-24: 6rem;     /* 96px */
  --space-32: 8rem;     /* 128px */

  /* Sombras Discretas e Editoriais (Ambient Dark Occlusion - Sem Glow Exagerado) */
  --shadow-subtle: 0 1px 2px rgba(0, 0, 0, 0.4);
  --shadow-card: 0 4px 16px rgba(0, 0, 0, 0.5);
  --shadow-elevated: 0 12px 32px rgba(0, 0, 0, 0.65);
  --shadow-header: 0 4px 24px rgba(0, 0, 0, 0.75);

  /* Raios de Borda (Minimalista - Sem excesso de cantos arredondados) */
  --radius-none: 0px;
  --radius-xs: 2px;
  --radius-sm: 4px;
  --radius-md: 6px;

  /* Transições Refinadas */
  --duration-fast: 150ms;
  --duration-normal: 250ms;
  --duration-slow: 400ms;
  --ease-editorial: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);

  --transition-fast: var(--duration-fast) var(--ease-editorial);
  --transition-base: var(--duration-normal) var(--ease-editorial);
  --transition-slow: var(--duration-slow) var(--ease-editorial);

  /* Breakpoints & Larguras de Layout */
  --breakpoint-mobile: 390px;
  --breakpoint-tablet: 834px;
  --breakpoint-desktop: 1440px;

  --container-max: 1440px;
  --container-tablet: 834px;
  --container-mobile: 390px;

  /* Dimensões Estruturais (Mobile First) */
  --header-height: 64px;
  --header-height-scrolled: 60px;

  /* Z-Index */
  --z-negative: -1;
  --z-base: 1;
  --z-elevated: 10;
  --z-sticky: 100;
  --z-header: 1000;
  --z-modal: 2000;

  /* Overlays Editoriais (Garante legibilidade sobre fotos reais sem peso excessivo) */
  --gradient-hero-overlay: linear-gradient(
    90deg,
    rgba(10, 12, 14, 0.96) 0%,
    rgba(10, 12, 14, 0.88) 38%,
    rgba(10, 12, 14, 0.45) 68%,
    rgba(10, 12, 14, 0.12) 100%
  );
  --gradient-hero-mobile: linear-gradient(
    180deg,
    rgba(10, 12, 14, 0.88) 0%,
    rgba(10, 12, 14, 0.72) 38%,
    rgba(10, 12, 14, 0.40) 70%,
    rgba(10, 12, 14, 0.85) 100%
  );
  --gradient-card-overlay: linear-gradient(
    180deg,
    rgba(10, 12, 14, 0) 40%,
    rgba(10, 12, 14, 0.9) 100%
  );

  /* Dimensões de Botões e Controles */
  --btn-height-sm: 40px;
  --btn-height-md: 48px;
  --btn-height-lg: 54px;
  --btn-padding-x: 1.5rem;
}

@media (min-width: 992px) {
  :root {
    --header-height: 84px;
    --header-height-scrolled: 72px;
  }
}




/* ==================== */

/* ==========================================================================
   RESET & REGRAS BASE DE ACESSIBILIDADE
   Estilo editorial, alto contraste e performance
   ========================================================================== */

/* Box Sizing Padrão */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* HTML Base */
html {
  scroll-behavior: smooth;
  font-size: 100%;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  background-color: var(--color-bg);
  color-scheme: dark;
}

/* Body Base */
body {
  min-height: 100vh;
  background-color: var(--color-bg);
  color: var(--color-text-primary);
  font-family: var(--font-body);
  font-size: var(--text-base);
  font-weight: var(--font-weight-regular);
  line-height: var(--leading-normal);
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: clip;
}

/* Tipografia Base de Títulos */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--color-text-primary);
  font-weight: var(--font-weight-bold);
  line-height: var(--leading-tight);
  letter-spacing: var(--tracking-tight);
}

p {
  color: var(--color-text-secondary);
}

/* Elementos de Mídia & Imagens */
img,
picture,
video,
canvas,
svg {
  display: block;
  max-width: 100%;
  height: auto;
}

img {
  object-fit: cover;
}

/* Links */
a {
  color: inherit;
  text-decoration: none;
  transition: color var(--transition-fast), border-color var(--transition-fast);
}

/* Listas */
ul,
ol {
  list-style: none;
}

/* Botões e Entradas Interativas */
button,
input,
textarea,
select {
  font: inherit;
  color: inherit;
  background: none;
  border: none;
}

button {
  cursor: pointer;
}

/* Acessibilidade: Foco Visível de Alto Contraste */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
  border-radius: var(--radius-xs);
}

/* Acessibilidade: Skip Link para Conteúdo Principal */
.skip-link {
  position: absolute;
  top: -100px;
  left: var(--space-4);
  z-index: var(--z-modal);
  padding: var(--space-3) var(--space-5);
  background-color: var(--color-accent);
  color: var(--color-text-primary);
  font-family: var(--font-heading);
  font-weight: var(--font-weight-semibold);
  font-size: var(--text-sm);
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  border-radius: var(--radius-xs);
  transition: top var(--transition-fast);
}

.skip-link:focus {
  top: var(--space-4);
}

/* Acessibilidade: Redução de Movimento (prefers-reduced-motion) */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}




/* ==================== */

/* ==========================================================================
   LAYOUT BASE RESPONSIVO
   Grid, Containers (1440px / 834px / 390px) e Header Fixo
   ========================================================================== */

/* Container Centralizado e Fluido */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: 20px; /* Margens laterais consistentes de 20px (360px a 430px) */
}

@media (min-width: 834px) {
  .container {
    padding-inline: var(--space-8); /* Tablet 834px: 32px */
  }
}

@media (min-width: 1440px) {
  .container {
    padding-inline: var(--space-12); /* Desktop 1440px: 48px */
  }
}

/* Estrutura Principal da Página */
.site-wrapper {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  width: 100%;
  position: relative;
  overflow-x: clip;
}

.site-main {
  flex: 1 0 auto;
  width: 100%;
  padding-top: var(--header-height);
  position: relative;
}

/* Âncoras com deslocamento seguro abaixo do header fixo */
section[id] {
  scroll-margin-top: calc(var(--header-height) + 12px);
}

/* Header Fixo com Alteração Sutil no Scroll */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  width: 100%;
  height: var(--header-height);
  z-index: var(--z-header);
  background-color: transparent;
  border-bottom: 1px solid transparent;
  transition: background-color var(--transition-base),
              border-color var(--transition-base),
              backdrop-filter var(--transition-base),
              height var(--transition-base),
              box-shadow var(--transition-base);
}

/* Estado ativo pós-scroll: sutil, translúcido e editorial */
.site-header.is-scrolled {
  height: var(--header-height-scrolled);
  background-color: rgba(10, 12, 14, 0.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom-color: var(--color-border-subtle);
  box-shadow: var(--shadow-header);
}

.header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

/* Footer Estrutural */
.site-footer {
  width: 100%;
  background-color: var(--color-surface-base);
  border-top: 1px solid var(--color-border-subtle);
  padding-block: var(--space-12);
}

/* Utilitários de Alinhamento e Grid */
.flex-row {
  display: flex;
  align-items: center;
}

.flex-between {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.grid-base {
  display: grid;
  gap: var(--space-6);
}

/* Componentes Base: Botões Editoriais Automotivos */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  font-family: var(--font-heading);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-bold);
  letter-spacing: var(--tracking-wider);
  text-transform: uppercase;
  border-radius: var(--radius-xs);
  text-decoration: none;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color var(--transition-fast),
              border-color var(--transition-fast),
              color var(--transition-fast),
              transform var(--transition-fast);
}

.btn--primary {
  height: var(--btn-height-md);
  padding-inline: var(--btn-padding-x);
  background-color: var(--color-accent);
  color: var(--color-text-primary);
  border: 1px solid var(--color-accent);
}

.btn--primary:hover {
  background-color: var(--color-accent-hover);
  border-color: var(--color-accent-hover);
  transform: translateY(-1px);
}

.btn--outline {
  height: var(--btn-height-md);
  padding-inline: var(--btn-padding-x);
  background-color: transparent;
  color: var(--color-text-primary);
  border: 1px solid rgba(247, 246, 243, 0.28);
}

.btn--outline:hover {
  border-color: var(--color-text-primary);
  background-color: rgba(247, 246, 243, 0.04);
}

.btn--header {
  height: var(--btn-height-sm);
  padding-inline: var(--space-5);
  background-color: transparent;
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
}

.btn--header:hover {
  background-color: var(--color-accent);
  color: var(--color-text-primary);
}

/* Proteção Estrita contra Overflow */
.overflow-guard {
  max-width: 100vw;
  overflow-x: clip;
}




/* ==================== */

/* ==========================================================================
   ANIMAÇÕES DISCRETAS ON-SCROLL
   Transições editoriais minimalistas: fade + translateY curto
   Respeita rigorosamente prefers-reduced-motion
   ========================================================================== */

/* Elemento base com atributo [data-reveal] (Visível por padrão se JS falhar) */
[data-reveal] {
  opacity: 1;
  transform: none;
}

/* Estado oculto ativado apenas com JavaScript ativo no documento */
.js [data-reveal] {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity 600ms var(--ease-editorial),
              transform 600ms var(--ease-editorial);
  will-change: opacity, transform;
}

/* Estado Visível acionado pelo IntersectionObserver */
.js [data-reveal].is-revealed {
  opacity: 1;
  transform: translateY(0);
}

/* Variação: Somente Fade (sem deslocamento) */
.js [data-reveal="fade"] {
  transform: none;
}

.js [data-reveal="fade"].is-revealed {
  transform: none;
}

/* Delays Escalonados Sutis para Composição Editorial */
[data-reveal-delay="100"] {
  transition-delay: 100ms;
}

[data-reveal-delay="200"] {
  transition-delay: 200ms;
}

[data-reveal-delay="300"] {
  transition-delay: 300ms;
}

[data-reveal-delay="400"] {
  transition-delay: 400ms;
}





/* ==================== */

/* ==========================================================================
   HEADER & NAVEGAÇÃO INSTITUCIONAL
   Estilo minimalista, compacto, editorial e premium
   ========================================================================== */

.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  width: 100%;
  height: var(--header-height);
  z-index: var(--z-header);
  background-color: rgba(10, 12, 14, 0.92);
  border-bottom: 1px solid var(--color-border-subtle);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  transition: height var(--transition-base),
              background-color var(--transition-base),
              box-shadow var(--transition-base),
              border-color var(--transition-base);
}

.site-header.is-scrolled {
  height: var(--header-height-scrolled);
  background-color: rgba(10, 12, 14, 0.96);
  box-shadow: var(--shadow-header);
  border-bottom-color: var(--color-border-default);
}

.header-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

/* Marca / Logotipo */
.header-brand {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  transition: opacity var(--transition-fast);
}

.header-brand:hover {
  opacity: 0.9;
}

.header-logo {
  height: 28px;
  width: auto;
  max-width: 118px;
  object-fit: contain;
  display: block;
}

@media (min-width: 834px) {
  .header-logo {
    height: 40px;
    max-width: 200px;
  }
}

/* Navegação Desktop */
.site-nav {
  display: none;
}

@media (min-width: 992px) {
  .site-nav {
    display: block;
  }

  .nav-list {
    display: flex;
    align-items: center;
    gap: var(--space-8);
  }

  .nav-link {
    position: relative;
    font-family: var(--font-body);
    font-size: var(--text-sm);
    font-weight: var(--font-weight-medium);
    color: var(--color-text-secondary);
    padding-block: var(--space-2);
    letter-spacing: var(--tracking-wide);
    transition: color var(--transition-fast);
  }

  .nav-link:hover {
    color: var(--color-text-primary);
  }

  /* Link Ativo com traço laranja Storm sutil */
  .nav-link.is-active {
    color: var(--color-text-primary);
    font-weight: var(--font-weight-semibold);
  }

  .nav-link.is-active::after {
    content: "";
    position: absolute;
    bottom: -4px;
    left: 0;
    right: 0;
    height: 2px;
    background-color: var(--color-accent);
    border-radius: var(--radius-xs);
  }
}

/* Ações do Header (Botão CTA e Hamburger Mobile) */
.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

/* Botão CTA no Header (Desktop) */
.header-cta {
  display: none;
}

@media (min-width: 768px) {
  .header-cta {
    display: inline-flex;
    gap: var(--space-2);
    font-size: var(--text-xs);
    font-weight: var(--font-weight-bold);
    letter-spacing: var(--tracking-wider);
  }

  .header-cta svg {
    color: var(--color-accent);
    transition: color var(--transition-fast);
  }

  .header-cta:hover svg {
    color: var(--color-text-primary);
  }
}

/* Botão Hamburger (Mobile) */
.mobile-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  background: transparent;
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-xs);
  color: var(--color-text-primary);
  padding: 0;
  transition: background-color var(--transition-fast),
              border-color var(--transition-fast),
              color var(--transition-fast);
}

.mobile-toggle:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}

@media (min-width: 992px) {
  .mobile-toggle {
    display: none;
  }
}

/* Painel de Menu Mobile (Drawer Minimalista) */
.mobile-drawer {
  position: fixed;
  top: 0;
  right: -100%;
  width: 100%;
  max-width: 360px;
  height: 100vh;
  background-color: var(--color-surface-base);
  border-left: 1px solid var(--color-border-default);
  z-index: var(--z-modal);
  padding: var(--space-6) var(--space-6) var(--space-8);
  display: flex;
  flex-direction: column;
  transition: right 350ms var(--ease-editorial);
  box-shadow: -8px 0 32px rgba(0, 0, 0, 0.8);
}

.mobile-drawer.is-open {
  right: 0;
}

.mobile-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: var(--space-6);
  border-bottom: 1px solid var(--color-border-subtle);
}

.mobile-drawer-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  color: var(--color-text-secondary);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-xs);
  transition: color var(--transition-fast), border-color var(--transition-fast);
}

.mobile-drawer-close:hover {
  color: var(--color-accent);
  border-color: var(--color-accent);
}

.mobile-drawer-nav {
  margin-top: var(--space-6);
  flex: 1;
}

.mobile-nav-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.mobile-nav-link {
  display: block;
  font-family: var(--font-heading);
  font-size: var(--text-lg);
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-secondary);
  padding: var(--space-3) 0;
  border-bottom: 1px solid rgba(247, 246, 243, 0.04);
  transition: color var(--transition-fast), padding-left var(--transition-fast);
}

.mobile-nav-link:hover,
.mobile-nav-link.is-active {
  color: var(--color-accent);
  padding-left: var(--space-2);
}

.mobile-drawer-footer {
  margin-top: auto;
  padding-top: var(--space-6);
  border-top: 1px solid var(--color-border-subtle);
}

.mobile-drawer-footer .btn {
  width: 100%;
}

/* Backdrop escuro do menu mobile */
.mobile-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(10, 12, 14, 0.7);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  z-index: calc(var(--z-modal) - 1);
  opacity: 0;
  visibility: hidden;
  transition: opacity 300ms var(--ease-editorial),
              visibility 300ms var(--ease-editorial);
}

.mobile-backdrop.is-visible {
  opacity: 1;
  visibility: visible;
}




/* ==================== */

/* ==========================================================================
   HERO & FAIXAS DE CONFIANÇA INICIAIS
   Composição editorial de alto impacto alinhada estritamente ao mockup
   ========================================================================== */

/* Seção Hero Principal */
.hero-section {
  position: relative;
  width: 100%;
  min-height: auto;
  display: flex;
  flex-direction: column;
  background-color: var(--color-bg);
  overflow: hidden;
}

@media (min-width: 992px) {
  .hero-section {
