/* ==========================================================================
   SEÇÃO SERVIÇOS - STORM AUTOMOTIVE
   Fidelidade absoluta ao mockup aprovado (img2 / media_1789069232066.png)
   ========================================================================== */

.services-section {
  position: relative;
  width: 100%;
  background-color: #F8F8F6; /* Fundo off-white refinado */
  color: var(--color-bg);
  padding-top: clamp(32px, 4vw, 56px);
  padding-bottom: clamp(20px, 2.5vw, 28px);
}

/* Cabeçalho da Seção */
.services-header {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  margin-bottom: clamp(24px, 2.8vw, 32px);
}

@media (min-width: 992px) {
  .services-header {
    flex-direction: row;
    align-items: flex-end;
    justify-content: space-between;
    gap: var(--space-8);
  }
}

.services-header-left {
  max-width: 720px;
}

.services-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: var(--space-3);
  font-family: var(--font-heading);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-bold);
  color: var(--color-accent);
  letter-spacing: var(--tracking-widest);
