  font-size: clamp(1.65rem, 6.5vw, 3rem); /* 26px a 32px no mobile */
  font-weight: var(--font-weight-extrabold);
  line-height: 1.12;
  letter-spacing: -0.025em;
  color: #0E1217;
  text-transform: uppercase;
}

.services-title .text-accent {
  color: var(--color-accent);
