}

.services-header-right {
  max-width: 420px;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.services-intro {
  font-family: var(--font-body);
  font-size: 0.9375rem;
  line-height: 1.5;
  color: #6B7280;
}

@media (min-width: 992px) {
  .desktop-only {
    display: block;
  }
}

.services-link {
