}

.services-link:hover {
  color: var(--color-accent);
}

.services-link:hover svg {
  transform: translateX(4px);
}

/* ==========================================================================
   GRADE EDITORIAL DE SERVIÇOS
   Mobile: 1 coluna padronizada (min-height: 240px)
   Desktop: Card Alto | 2 Cards Horizontais | Card Alto
   ========================================================================== */

.services-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 992px) {
  .services-grid {
    grid-template-columns: 1fr 1.32fr 1fr;
    gap: 24px;
    align-items: stretch;
  }
}

.services-column-center {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

@media (min-width: 992px) {
  .services-column-center {
    gap: 24px;
    height: 100%;
  }
}

/* Componente Base do Card */
.service-card {
  position: relative;
  display: block;
  background-color: #0A0C0E;
  border-radius: 6px;
  overflow: hidden;
  text-decoration: none;
  min-height: 240px; /* Padronizado no mobile entre 220 e 250px */
  box-shadow: 0 10px 30px rgba(10, 12, 14, 0.08);
  transition: transform 350ms var(--ease-editorial),
              box-shadow 350ms var(--ease-editorial),
              border-color 350ms var(--ease-editorial);
  cursor: pointer;
}

.service-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 18px 40px rgba(10, 12, 14, 0.16);
}

/* Imagem de Fundo */
.service-card-media {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  z-index: 1;
}

.service-card-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 650ms var(--ease-editorial);
}

/* Object positions afinados por serviço no mobile */
.services-grid > .service-card--tall:first-child .service-card-img {
  object-position: center 30%;
}

.services-column-center .service-card:first-child .service-card-img {
  object-position: right 35%;
}

.services-column-center .service-card:last-child .service-card-img {
  object-position: center 40%;
}

.services-grid > .service-card--tall:last-child .service-card-img {
  object-position: center 35%;
}

.service-card:hover .service-card-img {
  transform: scale(1.035);
}

/* Overlay Geral para Contraste */
.service-card-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(10, 12, 14, 0.15) 0%,
    rgba(10, 12, 14, 0.45) 35%,
    rgba(10, 12, 14, 0.88) 70%,
    rgba(10, 12, 14, 0.98) 100%
  );
  z-index: 2;
}

/* --------------------------------------------------------------------------
   Card Alto (01 e 04)
   -------------------------------------------------------------------------- */
.service-card--tall {
  min-height: 240px;
}

@media (min-width: 992px) {
  .service-card--tall {
    min-height: 540px;
    height: 100%;
  }

  .service-card--tall .service-card-overlay {
    background: linear-gradient(
      180deg,
      rgba(10, 12, 14, 0) 25%,
      rgba(10, 12, 14, 0.35) 45%,
      rgba(10, 12, 14, 0.88) 72%,
      rgba(10, 12, 14, 0.98) 100%
    );
  }
}

.service-card-body {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 20px;
  z-index: 3;
  display: flex;
  flex-direction: column;
  max-width: calc(100% - 60px); /* Previne sobreposição com a seta circular */
}

@media (min-width: 992px) {
  .service-card--tall .service-card-body {
    padding: 28px 24px;
    max-width: 100%;
  }
}

/* --------------------------------------------------------------------------
   Card Horizontal (02 e 03)
   -------------------------------------------------------------------------- */
.service-card--horizontal {
  min-height: 240px;
}

@media (min-width: 992px) {
  .service-card--horizontal {
    flex: 1;
    min-height: calc((540px - 24px) / 2);
    display: flex;
    align-items: center;
  }

  .service-card--horizontal .service-card-img {
    object-position: right center;
  }

  .service-card--horizontal .service-card-overlay {
    background: linear-gradient(
      90deg,
      #0A0C0E 0%,
      #0A0C0E 38%,
      rgba(10, 12, 14, 0.85) 54%,
      rgba(10, 12, 14, 0.25) 75%,
      rgba(10, 12, 14, 0) 100%
    );
  }

  .service-card--horizontal .service-card-body {
    position: relative;
    padding: 28px 24px;
    max-width: 310px;
  }
}

/* --------------------------------------------------------------------------
   Tipografia Interna dos Cards
   -------------------------------------------------------------------------- */
.service-number {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: var(--font-weight-bold);
