}

.service-title {
  font-family: var(--font-heading);
  font-size: clamp(1.25rem, 5vw, 1.375rem); /* Entre 20px e 22px */
  font-weight: var(--font-weight-extrabold);
  color: #FFFFFF;
  letter-spacing: -0.02em;
  line-height: 1.15;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.service-desc {
  font-family: var(--font-body);
  font-size: 0.875rem; /* 14px a 15px */
  line-height: 1.45;
  color: #9CA3AF;
  margin-bottom: 0;
  max-width: 260px;
