  background-color: rgba(10, 12, 14, 0.94);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  padding: 12px 20px;
  border-top-right-radius: var(--radius-sm);
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  border-right: 1px solid rgba(255, 255, 255, 0.08);
  z-index: 2;
}

.about-badge-slash {
  font-family: var(--font-heading);
  font-size: 1.85rem;
  font-weight: 800;
  color: var(--color-accent);
  line-height: 1;
}

.about-badge-content {
  display: flex;
  flex-direction: column;
}

.about-badge-value {
  font-family: var(--font-heading);
  font-size: 1.15rem;
  font-weight: 800;
  color: #FFFFFF;
  line-height: 1.1;
  letter-spacing: -0.01em;
}

.about-badge-label {
  font-family: var(--font-heading);
  font-size: 0.65rem;
  font-weight: 700;
  color: #A0AEC0;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* Coluna Direita: Conteúdo Editorial */
.about-content {
  display: flex;
  flex-direction: column;
}

.about-header-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-4);
  margin-bottom: var(--space-2);
}

.about-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: var(--space-3);
  font-family: var(--font-heading);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-bold);
  color: var(--color-accent);
  letter-spacing: var(--tracking-widest);
  text-transform: uppercase;
}

/* Assinatura de Parede / Tagline Manuscrita Sutil */
.about-script-tagline {
  display: none;
  font-family: 'Caveat', cursive, sans-serif;
  font-weight: 600;
  font-size: 1.25rem;
  line-height: 1.15;
  color: #7A8490;
  text-align: right;
  max-width: 170px;
}

.about-script-tagline span {
  display: block;
}

.about-script-tagline .tagline-highlight {
  color: #555D66;
  position: relative;
  display: inline-block;
}

.about-script-tagline .tagline-highlight::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 10%;
  width: 90%;
  height: 2px;
  background-color: var(--color-accent);
  border-radius: 2px;
}

@media (min-width: 1200px) {
  .about-script-tagline {
    display: block;
  }
}

/* Título em 2 Linhas: Linha 1 = TRABALHO SÉRIO / Linha 2 = QUE GERA CONFIANÇA */
.about-title {
  font-family: var(--font-heading);
  font-size: clamp(1.65rem, 6.5vw, 2.75rem); /* 26px a 32px no mobile */
  font-weight: var(--font-weight-extrabold);
  line-height: 1.12;
  letter-spacing: -0.025em;
  color: var(--color-bg);
  text-transform: uppercase;
  margin-bottom: 14px;
}

.about-title-line1,
.about-title-line2 {
  display: block;
}

@media (min-width: 400px) {
  .about-title-line1,
  .about-title-line2 {
    white-space: nowrap;
  }
}

.about-title .text-accent {
  color: var(--color-accent);
}

.about-lead {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.5;
  color: #555D66;
  margin-bottom: 20px;
  max-width: 580px;
}

/* Grid de Diferenciais: Lado a Lado no Mobile conforme solicitação */
.about-features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  align-items: stretch;
  margin-bottom: clamp(18px, 2vw, 24px);
  padding-block: 16px;
  border-top: 1px solid rgba(10, 12, 14, 0.08);
  border-bottom: 1px solid rgba(10, 12, 14, 0.08);
}

.about-feature-item {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  padding-right: 6px;
  border-right: 1px solid rgba(10, 12, 14, 0.08);
}

.about-feature-item:last-child {
  border-right: none;
  padding-right: 0;
}

.about-feature-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--color-accent);
}

.about-feature-icon svg {
  width: 22px;
  height: 22px;
}

.about-feature-text {
  font-family: var(--font-heading);
  font-size: 0.65rem;
  font-weight: var(--font-weight-bold);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--color-bg);
  line-height: 1.25;
}

@media (min-width: 600px) {
  .about-features-grid {
    gap: 0;
    align-items: center;
  }

  .about-feature-item {
    flex-direction: row;
    gap: var(--space-3);
    padding-inline: var(--space-4);
    border-right: 1px solid rgba(10, 12, 14, 0.1);
  }

  .about-feature-item:first-child {
    padding-left: 0;
  }

  .about-feature-item:last-child {
    border-right: none;
    padding-right: 0;
  }

  .about-feature-icon svg {
    width: 24px;
    height: 24px;
  }

  .about-feature-text {
    font-size: 0.725rem;
    letter-spacing: var(--tracking-wider);
  }
}

/* Botão CTA da Seção Sobre */
.about-btn {
  width: 100%;
  height: 50px;
  min-height: 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding-inline: var(--space-6);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-bold);
  letter-spacing: var(--tracking-wider);
  text-transform: uppercase;
}

@media (min-width: 480px) {
  .about-btn {
    width: fit-content;
    align-self: flex-start;
    padding-inline: var(--space-8);
    height: 52px;
  }
}

.about-btn svg {
  transition: transform var(--transition-fast);
}

.about-btn:hover svg {
  transform: translateX(3px);
}



/* ==================== */

/* ==========================================================================
   SEÇÃO MÉTODO STORM
   Design horizontal escuro editorial, fotografia de alta precisão com mecânico à direita,
   três etapas com ícones lineares, divisores e conectores.
   ========================================================================== */

.method-section {
  position: relative;
  width: 100%;
  background-color: var(--color-bg); /* Grafite/Preto Profundo #0A0C0E */
  color: var(--color-text-primary);
  padding-block: clamp(30px, 3.5vw, 48px);
  overflow: hidden;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

/* Fundo com Imagem HQ e Sobreposição Editorial */
.method-backdrop {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.method-bg-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center right;
  opacity: 0.85;
}

/* Gradiente direcional escuro para garantir legibilidade máxima dos textos */
.method-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(10, 12, 14, 0.98) 0%,
    rgba(10, 12, 14, 0.95) 38%,
    rgba(10, 12, 14, 0.82) 58%,
    rgba(10, 12, 14, 0.40) 80%,
    rgba(10, 12, 14, 0.20) 100%
  );
}

@media (max-width: 768px) {
  .method-overlay {
    background: linear-gradient(
      180deg,
      rgba(10, 12, 14, 0.97) 0%,
      rgba(10, 12, 14, 0.94) 50%,
      rgba(10, 12, 14, 0.88) 100%
    );
  }
}

.method-container {
  position: relative;
  z-index: 1;
}

/* Linha Superior: Título + Texto de Apoio */
.method-header-row {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  margin-bottom: clamp(24px, 2.8vw, 32px);
}

@media (min-width: 992px) {
  .method-header-row {
    flex-direction: row;
    align-items: flex-end;
    justify-content: space-between;
    gap: var(--space-8);
  }
}

.method-header-left {
  max-width: 640px;
}

.method-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: var(--space-3);
  font-family: var(--font-heading);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-bold);
  color: var(--color-accent);
  letter-spacing: var(--tracking-widest);
  text-transform: uppercase;
  margin-bottom: var(--space-3);
}

.method-title {
  font-family: var(--font-heading);
  font-size: clamp(1.65rem, 6.5vw, 2.75rem); /* 26px a 32px no mobile */
  font-weight: var(--font-weight-extrabold);
  line-height: 1.12;
  letter-spacing: -0.025em;
  color: #FFFFFF;
  text-transform: uppercase;
}

.method-title-line1,
.method-title-line2 {
  display: block;
}

@media (min-width: 480px) {
  .method-title-line1,
  .method-title-line2 {
    white-space: nowrap;
  }
}

.method-title .text-accent {
  color: var(--color-accent);
}

.method-lead {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.5;
  color: #A0AEC0;
  max-width: 440px;
  margin-bottom: 0;
}

/* Grid das 3 Etapas */
.method-steps-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px; /* Separação de 20 a 24px no mobile */
  position: relative;
}

@media (min-width: 992px) {
  .method-steps-grid {
    grid-template-columns: 1fr 1fr 1fr;
    gap: 0;
  }
}

/* Card Individual de Etapa */
.method-step-card {
  position: relative;
  display: flex;
  flex-direction: column;
}

@media (min-width: 992px) {
  .method-step-card {
    padding-inline: clamp(24px, 2.5vw, 40px);
    border-left: 1px solid rgba(255, 255, 255, 0.12);
  }

  .method-step-card:first-child {
    padding-left: clamp(24px, 2.5vw, 36px);
    border-left: 2px solid var(--color-accent);
  }

  .method-step-card:last-child {
    padding-right: 0;
  }
}

/* Número e Linha de Destaque */
.method-step-number-row {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-bottom: 12px;
}

.method-step-num {
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 800;
  color: var(--color-accent);
  letter-spacing: 0.05em;
}

.method-step-dash {
  width: 20px;
  height: 2px;
  background-color: var(--color-accent);
  border-radius: 1px;
}

/* Linha Principal da Etapa: Ícone + Título + Seta Conectora */
.method-step-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  margin-bottom: 12px;
}

.method-step-header {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.method-step-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  color: var(--color-accent);
  flex-shrink: 0;
}

.method-step-icon svg {
  width: 32px;
  height: 32px;
}

.method-step-title {
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 800;
  line-height: 1.25;
  color: #FFFFFF;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

/* Seta de Conexão no Desktop */
.method-step-arrow {
  display: none;
  color: rgba(255, 255, 255, 0.45);
  transition: transform var(--transition-fast), color var(--transition-fast);
}

@media (min-width: 992px) {
  .method-step-arrow {
    display: flex;
    align-items: center;
    margin-left: auto;
  }

  .method-step-card:hover .method-step-arrow {
    transform: translateX(4px);
    color: var(--color-accent);
  }
}

/* Descrição da Etapa */
.method-step-desc {
  font-family: var(--font-body);
  font-size: 0.875rem;
  line-height: 1.55;
  color: #8C949E;
  max-width: 320px;
}

/* Linha de Progresso Vertical no Mobile */
@media (max-width: 991px) {
  .method-steps-grid {
    padding-left: 28px;
    gap: 20px;
  }

  .method-steps-grid::before {
    content: '';
    position: absolute;
    top: 10px;
    bottom: 20px;
    left: 6px;
    width: 2px;
    background: linear-gradient(
      180deg,
      var(--color-accent) 0%,
      rgba(255, 90, 31, 0.4) 70%,
      rgba(255, 255, 255, 0.1) 100%
    );
  }

  .method-step-card {
    position: relative;
    padding-bottom: 0;
  }

  .method-step-card::before {
    content: '';
    position: absolute;
    top: 6px;
    left: -26px;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background-color: var(--color-accent);
    box-shadow: 0 0 8px rgba(255, 90, 31, 0.7);
  }
}



/* ==================== */

/* ==========================================================================
   SEÇÃO NOSSA ESTRUTURA
   Fundo off-white, galeria editorial de alta precisão
   - Mobile: Coluna única sequencial (Chamada -> Título -> Descrição -> 3 Fotos -> Botão)
   - Desktop: 2 Colunas (Conteúdo à esquerda + Galeria assimétrica de 5 fotos à direita)
   ========================================================================== */

.structure-section {
  position: relative;
  width: 100%;
  background-color: var(--color-text-primary); /* Off-white #F7F6F3 */
  color: var(--color-bg);
  padding-block: 32px;
  border-top: 1px solid rgba(10, 12, 14, 0.06);
}

/* Layout Mobile Padrão: Coluna Única */
.structure-layout {
  display: flex;
  flex-direction: column;
  width: 100%;
}

/* No mobile, achata a intro para posicionar o botão após a galeria */
.structure-intro {
  display: contents;
}

.structure-eyebrow {
  order: 1;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-size: 0.6875rem;
  font-weight: var(--font-weight-bold);
  color: var(--color-accent);
  letter-spacing: var(--tracking-widest);
  text-transform: uppercase;
  margin-bottom: 8px;
}

.structure-title {
  order: 2;
  font-family: var(--font-heading);
  font-size: clamp(1.65rem, 6.2vw, 2.25rem);
  font-weight: var(--font-weight-extrabold);
  line-height: 1.12;
  letter-spacing: -0.025em;
  color: var(--color-bg);
  text-transform: uppercase;
  margin-bottom: 12px;
}

.structure-title-line1,
.structure-title-line2 {
  display: block;
}

.structure-title .text-accent {
  color: var(--color-accent);
}

.structure-lead {
  order: 3;
  font-family: var(--font-body);
  font-size: 0.9375rem;
  line-height: 1.5;
  color: #555D66;
  margin-bottom: 20px;
  max-width: 100%;
}

/* Galeria Editorial Mobile: Coluna Única de 3 Imagens */
.structure-gallery {
  order: 4;
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: 100%;
}

.structure-gallery-row {
  display: contents;
}

/* Itens da Galeria */
.structure-item {
  position: relative;
  border-radius: var(--radius-sm);
  overflow: hidden;
  box-shadow: 0 6px 20px rgba(10, 12, 14, 0.08);
  border: 1px solid rgba(10, 12, 14, 0.08);
  background-color: #0A0C0E;
  width: 100%;
  height: auto;
}

.structure-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 600ms var(--ease-editorial);
}

.structure-item:hover .structure-img {
  transform: scale(1.03);
}

/* Sobreposição sutil no hover */
.structure-item-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 65%, rgba(10, 12, 14, 0.35) 100%);
  opacity: 0;
  transition: opacity var(--transition-fast);
  pointer-events: none;
}

.structure-item:hover .structure-item-overlay {
  opacity: 1;
}

/* 3 Imagens Principais no Mobile */
.structure-item--panoramic {
  order: 1;
  aspect-ratio: 16 / 10;
}

.structure-item--panoramic .structure-img {
  object-position: center 50%;
}

.structure-item--diagnostico {
  order: 2;
  aspect-ratio: 16 / 10;
}

.structure-item--diagnostico .structure-img {
  object-position: center 40%;
}

.structure-item--recepcao {
  order: 3;
  aspect-ratio: 16 / 10;
}

.structure-item--recepcao .structure-img {
  object-position: center 60%;
}

/* Oculta fotos complementares no mobile */
.structure-item--elevador,
.structure-item--ferramental {
  display: none !important;
}

/* Botão CTA Conheça nosso espaço */
.structure-btn {
  order: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: 48px;
  height: 48px;
  padding-inline: 18px;
  margin-top: 20px;
  background-color: transparent;
  border: 1.5px solid #22252A;
  border-radius: var(--radius-sm);
  color: #0A0C0E;
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  text-decoration: none;
  transition: all var(--transition-fast);
}

.structure-btn svg {
  width: 16px;
  height: 16px;
  margin-left: 12px;
  flex-shrink: 0;
  transition: transform var(--transition-fast);
}

.structure-btn:hover {
  background-color: #0A0C0E;
  color: #FFFFFF;
  border-color: #0A0C0E;
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(10, 12, 14, 0.12);
}

.structure-btn:hover svg {
  transform: translateX(4px);
}

/* ==========================================================================
   DESKTOP (>= 992px): Preserva rigorosamente a composição editorial original
   ========================================================================== */
@media (min-width: 992px) {
  .structure-section {
    padding-top: clamp(28px, 3.5vw, 48px);
    padding-bottom: clamp(20px, 2.5vw, 28px);
  }

  .structure-layout {
    display: grid;
    grid-template-columns: 0.9fr 1.9fr;
    gap: clamp(24px, 3.5vw, 56px);
    align-items: center;
  }

  .structure-intro {
    display: flex;
    flex-direction: column;
    justify-content: center;
  }

  .structure-eyebrow {
    margin-bottom: 10px;
    font-size: var(--text-xs);
  }

  .structure-title {
    font-size: clamp(1.85rem, 1.35rem + 1.8vw, 2.75rem);
    margin-bottom: 14px;
  }

  .structure-title-line1,
  .structure-title-line2 {
    white-space: nowrap;
  }

  .structure-lead {
    font-size: clamp(0.9375rem, 0.875rem + 0.2vw, 1.0625rem);
    line-height: var(--leading-relaxed);
    max-width: 380px;
    margin-bottom: 0;
  }

  .structure-btn {
    width: fit-content;
    min-width: 200px;
    height: 42px;
    padding-inline: 18px;
    margin-top: 20px;
    font-size: 0.72rem;
    letter-spacing: 0.06em;
  }

  .structure-btn svg {
    margin-left: 14px;
  }

  .structure-gallery {
    display: flex;
    flex-direction: column;
    gap: 8px;
    width: 100%;
  }

  .structure-gallery-row {
    display: grid;
    gap: 8px;
    width: 100%;
  }

  .structure-gallery-row--top {
    grid-template-columns: 1.38fr 1fr;
  }

  .structure-gallery-row--top .structure-item {
    height: clamp(140px, 12.5vw, 195px);
    aspect-ratio: auto;
  }

  .structure-gallery-row--bottom {
    grid-template-columns: 0.77fr 0.61fr 1fr;
  }

  .structure-gallery-row--bottom .structure-item {
    height: clamp(115px, 10.5vw, 160px);
    aspect-ratio: auto;
  }

  .structure-item--elevador,
  .structure-item--ferramental {
    display: block !important;
  }
}



/* ==================== */

/* ==========================================================================
   SEÇÃO DEPOIMENTO
   Fundo off-white, composição editorial minimalista
   Componente estruturado para receber depoimento real com foto, citação e contexto
   ========================================================================== */

.testimonial-section {
  position: relative;
  width: 100%;
  background-color: var(--color-text-primary); /* Off-white #F7F6F3 */
  color: var(--color-bg);
  padding-top: clamp(20px, 2.5vw, 28px);
  padding-bottom: clamp(24px, 3vw, 40px);
  border-top: 1px solid rgba(10, 12, 14, 0.06);
}

.testimonial-header {
  margin-bottom: clamp(16px, 2vw, 24px);
}

.testimonial-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: var(--space-3);
  font-family: var(--font-heading);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-bold);
  color: var(--color-accent);
  letter-spacing: var(--tracking-widest);
  text-transform: uppercase;
}

/* Card Principal de Depoimento - Mobile First */
.testimonial-card {
  position: relative;
  background-color: #FFFFFF;
  border: 1px solid rgba(10, 12, 14, 0.08);
  border-radius: var(--radius-sm);
  padding: 20px; /* Padding interno de 20px no mobile */
  box-shadow: 0 10px 30px rgba(10, 12, 14, 0.04);
  display: grid;
  grid-template-columns: 60px 1fr;
  grid-template-areas:
    "avatar meta"
    "quote  quote"
    "aside  aside";
  column-gap: 14px;
  row-gap: 14px;
  align-items: center;
}

@media (max-width: 991px) {
  .testimonial-content {
    display: contents;
  }

  .testimonial-media {
    grid-area: avatar;
    width: 60px;
    max-width: 60px;
    margin: 0;
  }

  .testimonial-avatar-wrapper {
    width: 60px;
    height: 60px;
    border-radius: var(--radius-sm);
    overflow: hidden;
  }

  .testimonial-meta {
    grid-area: meta;
    display: flex;
    flex-direction: column;
    gap: 2px;
    margin-top: 0;
  }

  .testimonial-quote-box {
    grid-area: quote;
    margin-bottom: 0;
  }

  .testimonial-quote {
    font-size: 0.9375rem;
    line-height: 1.55;
    text-align: left;
  }

  .testimonial-aside {
    grid-area: aside;
    padding-top: 12px;
    border-top: 1px solid rgba(10, 12, 14, 0.08);
    opacity: 0.85;
  }

  .testimonial-script {
    font-size: 1.15rem;
    line-height: 1.25;
    margin-bottom: 8px;
  }
}

/* Elementos Básicos Compartilhados */
.testimonial-media {
  width: 100%;
}

.testimonial-avatar-wrapper {
  position: relative;
  aspect-ratio: 1 / 1;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background-color: #0A0C0E;
  border: 1px solid rgba(10, 12, 14, 0.08);
}

.testimonial-avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.testimonial-quote-box {
  margin-bottom: 0;
}

.testimonial-quote {
  font-family: var(--font-body);
  font-size: clamp(0.95rem, 0.88rem + 0.3vw, 1.075rem);
  font-weight: 500;
  line-height: 1.6;
  color: #1A1C1E;
  margin: 0;
  position: relative;
}

.testimonial-quote-mark {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: #0A0C0E;
  line-height: 0;
  vertical-align: -3px;
  margin-inline: 2px;
}

.testimonial-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.testimonial-author {
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 700;
  color: #0A0C0E;
  font-style: normal;
  letter-spacing: -0.01em;
}

.testimonial-context {
  font-family: var(--font-body);
  font-size: 0.8125rem;
  color: #6C757D;
}

.testimonial-aside {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.testimonial-script {
  font-family: 'Caveat', cursive, sans-serif;
  font-size: 1.35rem;
  line-height: 1.25;
  color: #7A8490;
  margin-bottom: var(--space-3);
}

.testimonial-accent-bar {
  width: 44px;
  height: 3px;
  background-color: var(--color-accent);
  border-radius: 2px;
}

/* Desktop: 3 Colunas Aprovadas */
@media (min-width: 992px) {
  .testimonial-card {
    grid-template-columns: 150px 1fr 220px;
    grid-template-areas: none;
    gap: clamp(28px, 3vw, 48px);
    padding: clamp(24px, 2.8vw, 32px);
  }

  .testimonial-media {
    max-width: 150px;
    margin-inline: auto;
  }

  .testimonial-avatar-wrapper {
    width: 100%;
  }

  .testimonial-content {
    display: flex;
    flex-direction: column;
  }

  .testimonial-quote-box {
    margin-bottom: var(--space-4);
  }

  .testimonial-meta {
    margin-top: var(--space-2);
  }

  .testimonial-aside {
    border-left: 1px solid rgba(10, 12, 14, 0.1);
    padding-left: clamp(24px, 2.5vw, 36px);
  }
}



/* ==================== */

/* ==========================================================================
   SEÇÃO CONTATO
   Grande seção final em grafite/preto, conversão direta via WhatsApp,
   informações comerciais e representação visual de mapa
   ========================================================================== */

.contact-section {
  position: relative;
  width: 100%;
  background-color: var(--color-bg); /* #0A0C0E */
  color: var(--color-text-primary);
  padding-top: clamp(28px, 3.5vw, 48px);
  padding-bottom: clamp(24px, 3vw, 40px);
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.contact-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-8);
  align-items: center;
}

@media (min-width: 992px) {
  .contact-layout {
    grid-template-columns: 1.15fr 0.95fr 1.35fr;
    gap: clamp(32px, 3.5vw, 64px);
    align-items: center;
  }
}

/* Coluna 1: Título e CTA WhatsApp */
.contact-cta-col {
  display: flex;
  flex-direction: column;
}

.contact-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: var(--space-3);
  font-family: var(--font-heading);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-bold);
  color: var(--color-accent);
  letter-spacing: var(--tracking-widest);
  text-transform: uppercase;
  margin-bottom: 10px;
}

.contact-title {
  font-family: var(--font-heading);
  font-size: clamp(1.65rem, 6.5vw, 2.75rem); /* 26px a 32px no mobile */
  font-weight: var(--font-weight-extrabold);
  line-height: 1.12;
  letter-spacing: -0.025em;
  color: #FFFFFF;
  text-transform: uppercase;
  margin-bottom: 14px;
}

.contact-title-line1,
.contact-title-line2 {
  display: block;
}

@media (min-width: 480px) {
  .contact-title-line1,
  .contact-title-line2 {
    white-space: nowrap;
  }
}

.contact-title .text-accent {
  color: var(--color-accent);
}

.contact-lead {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.5;
  color: #A0AEC0;
  margin-bottom: 20px;
  max-width: 400px;
}

/* Botão Verde WhatsApp */
.btn--whatsapp {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  background-color: #00A843;
  color: #FFFFFF;
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  text-decoration: none;
  height: 52px;
  min-height: 48px;
  padding: 0 22px;
  border-radius: 6px;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
  transition: all var(--transition-fast);
  width: 100%; /* Largura total disponível no mobile */
}

@media (min-width: 992px) {
  .btn--whatsapp {
    width: fit-content;
    padding: 0 26px;
    gap: 16px;
    font-size: 0.84rem;
    height: 56px;
  }
}

.btn--whatsapp svg.whatsapp-icon {
  width: 26px;
  height: 26px;
  fill: currentColor;
  flex-shrink: 0;
}

.btn--whatsapp svg.btn-arrow {
  width: 18px;
  height: 18px;
  stroke: currentColor;
  stroke-width: 2.5;
  flex-shrink: 0;
  transition: transform var(--transition-fast);
}

.btn--whatsapp:hover {
  background-color: #00BD4C;
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0, 168, 67, 0.32);
}

.btn--whatsapp:hover svg.btn-arrow {
  transform: translateX(4px);
}

/* Coluna 2: Informações Comerciais */
.contact-info-col {
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
  padding-left: 0;
}

@media (min-width: 992px) {
  .contact-info-col {
    border-left: 1px solid rgba(255, 255, 255, 0.08);
    padding-left: clamp(24px, 2.5vw, 40px);
    gap: var(--space-6);
  }
}

.contact-info-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-4);
}

.contact-info-icon-circle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.18);
  color: #FFFFFF;
  flex-shrink: 0;
}

.contact-info-icon-circle svg {
  width: 20px;
  height: 20px;
}

.contact-info-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.contact-info-label {
  font-family: var(--font-body);
  font-size: 0.8125rem;
  color: #A0AEC0;
}

.contact-info-value {
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 700;
  color: #FFFFFF;
  text-decoration: none;
  line-height: 1.4;
  transition: color var(--transition-fast);
  word-break: break-word;
}

a.contact-info-value:hover {
  color: var(--color-accent);
}

.contact-info-sub {
  font-family: var(--font-body);
  font-size: 0.775rem;
  color: #718096;
}

/* Coluna 3: Card com Mapa Real Integrado */
.contact-map-col {
  position: relative;
  width: 100%;
}

.contact-map-card {
  position: relative;
  width: 100%;
  height: 220px; /* Altura próxima de 220px no mobile */
  aspect-ratio: auto;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background-color: #121519;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.4);
}

@media (min-width: 992px) {
  .contact-map-card {
    height: auto;
    aspect-ratio: 16 / 10;
  }
}

.contact-map-iframe {
  width: 100%;
  height: 100%;
  border: 0;
  display: block;
}



/* ==================== */

/* ==========================================================================
   RODAPÉ GLOBAL (SITE FOOTER)
   Fundo preto profundo, hierarquia editorial, navegação, contato,
   redes sociais e barra de copyright
   ========================================================================== */

.site-footer {
  position: relative;
  width: 100%;
  background-color: #06080A; /* Preto profundo */
  color: var(--color-text-primary);
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: clamp(24px, 3vw, 32px);
  padding-bottom: clamp(14px, 2vw, 18px);
}

/* Grid do Rodapé */
.footer-grid {
  display: flex;
  flex-direction: column;
  gap: 22px; /* Blocos empilhados com gaps de 20 a 24px no mobile */
  margin-bottom: 24px;
}

@media (min-width: 992px) {
  .footer-grid {
    display: grid;
    grid-template-columns: 1.4fr 1fr 1.2fr 1fr;
    gap: clamp(32px, 3.5vw, 64px);
    margin-bottom: clamp(20px, 2.5vw, 28px);
  }
}

/* Coluna 1: Marca & Tagline */
.footer-brand-col {
  display: flex;
  flex-direction: column;
}

.footer-logo-link {
  display: inline-block;
  margin-bottom: var(--space-3);
  width: fit-content;
}

.footer-logo {
  width: 120px;
  height: auto;
  display: block;
}

@media (min-width: 992px) {
  .footer-logo {
    width: 160px;
  }
}

.footer-tagline {
  font-family: var(--font-body);
  font-size: 0.875rem;
  line-height: var(--leading-relaxed);
  color: #8C949E;
  max-width: 280px;
}

/* Títulos de Coluna */
.footer-col-title {
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 800;
  color: #FFFFFF;
  letter-spacing: var(--tracking-widest);
  text-transform: uppercase;
  margin-bottom: 12px;
}

@media (min-width: 992px) {
  .footer-col-title {
    margin-bottom: 16px;
  }
}

/* Coluna 2: Navegação (2 Colunas no Mobile para Economizar Altura) */
.footer-nav-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px 16px;
}

@media (min-width: 992px) {
  .footer-nav-list {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
  }
}

.footer-nav-link {
  font-family: var(--font-body);
  font-size: 0.875rem;
  color: #A0AEC0;
  text-decoration: none;
  transition: color var(--transition-fast), transform var(--transition-fast);
  display: inline-block;
}

.footer-nav-link:hover {
  color: var(--color-accent);
  transform: translateX(3px);
}

/* Coluna 3: Contato */
.footer-contact-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

@media (min-width: 992px) {
  .footer-contact-list {
    gap: var(--space-4);
  }
}

.footer-contact-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
}

.footer-contact-icon {
  color: var(--color-accent);
  flex-shrink: 0;
  margin-top: 2px;
}

.footer-contact-icon svg {
  width: 16px;
  height: 16px;
}

.footer-contact-text,
.footer-contact-link {
  font-family: var(--font-body);
  font-size: 0.875rem;
  color: #A0AEC0;
  text-decoration: none;
  line-height: 1.4;
  transition: color var(--transition-fast);
  word-break: break-word;
}

.footer-contact-link:hover {
  color: #FFFFFF;
}

/* Coluna 4: Redes Sociais */
.footer-social-col {
  display: flex;
  flex-direction: column;
}

.footer-social-list {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.footer-social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px; /* Área de toque mínima de 44px */
  height: 44px;
  border-radius: var(--radius-sm);
  background-color: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #A0AEC0;
  transition: all var(--transition-fast);
}

.footer-social-btn svg {
  width: 18px;
  height: 18px;
}

.footer-social-btn:hover {
  background-color: var(--color-accent);
  border-color: var(--color-accent);
  color: #FFFFFF;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(255, 90, 31, 0.35);
}

/* Barra Inferior (Direitos Reservados & Políticas) */
.footer-bottom-bar {
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  padding-top: 18px;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  align-items: center;
  justify-content: center;
}

@media (min-width: 992px) {
  .footer-bottom-bar {
    flex-direction: row;
    gap: 24px;
  }
}

.footer-copyright {
  font-family: var(--font-body);
  font-size: 0.775rem;
  color: #718096;
  text-align: center;
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 6px 12px;
  align-items: center;
  justify-content: center;
}

.footer-credit a {
  color: #a0aec0;
  text-decoration: none;
  transition: color var(--transition-fast);
}

.footer-credit a:hover {
  color: var(--color-accent);
}

.footer-legal-links {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.footer-legal-link {
  font-family: var(--font-body);
  font-size: 0.775rem;
  color: #718096;
  text-decoration: none;
  transition: color var(--transition-fast);
}

.footer-legal-link:hover {
  color: #A0AEC0;
}

.footer-legal-separator {
  color: rgba(255, 255, 255, 0.15);
  font-size: 0.775rem;
}



